512	/**
513	 * Full recount from the source tables. Called by the rollup job and by every
514	 * event that could have moved a counter — after recounting, the seat and
515	 * project totals are checked against the plan so a breach surfaces as an
516	 * event rather than waiting for the next write to be rejected.
517	 */
518	export async function recomputeUsage(
519	  orgId: OrgId,
520	): Promise<OrganizationUsage> {
521	  const usage = await usageRepo.recomputeUsage(orgId);
522	  const org = await orgRepo.findOrgById(orgId);
523	  if (!org) return usage;
524	
525	  const limits = getPlanLimits(org.plan);
526	
527	  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
528	    await emit("billing.limit_exceeded", {
529	      orgId,
530	      actorId: null,
531	      occurredAt: toIsoTimestamp(new Date()),
532	      resource: "seats",
533	      limit: limits.seats,
534	      used: usage.seatsUsed,
535	    });
536	  }
537	
538	  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
539	    await emit("billing.limit_exceeded", {
540	      orgId,
541	      actorId: null,
542	      occurredAt: toIsoTimestamp(new Date()),
543	      resource: "projects",
544	      limit: limits.projects,
545	      used: usage.projectsUsed,
546	    });
547	  }
548	
549	  return usage;
550	}
