552	/**
553	 * Every event that changes a counted resource nudges the cache. The deltas are
554	 * cheap; the periodic rollup is what corrects any drift they accumulate.
555	 */
556	export function registerUsageListeners(): Unsubscribe {
557	  const offs: Unsubscribe[] = [
558	    subscribe("issue.created", async (payload) => {
559	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
560	    }),
561	    subscribe("issue.archived", async (payload) => {
562	      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
563	    }),
564	    subscribe("project.created", async (payload) => {
565	      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
566	    }),
567	    subscribe("project.archived", async (payload) => {
568	      await usageRepo.incrementUsage(payload.orgId, {
569	        projectsUsed: -1,
570	        issuesUsed: -payload.issuesArchived,
571	      });
572	    }),
573	    subscribe("member.joined", async (payload) => {
574	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
575	    }),
576	    subscribe("member.removed", async (payload) => {
577	      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
578	    }),
579	  ];
580	
581	  return () => {
582	    for (const off of offs) off();
583	  };
584	}
