1017	    .delete(projectMembers)
1018	    .where(
1019	      and(
1020	        orgPredicate(projectMembers.orgId, orgId),
1021	        eq(projectMembers.projectId, projectId),
1022	        eq(projectMembers.userId, userId),
1023	      ),
1024	    )
1025	    .run();
1026	}
1027	
1028	export async function isProjectMember(
1029	  orgId: OrgId,
1030	  projectId: ProjectId,
1031	  userId: UserId,
1032	): Promise<boolean> {
1033	  const row = getDb()
1034	    .select({ userId: projectMembers.userId })
1035	    .from(projectMembers)
1036	    .where(
1037	      and(
1038	        orgPredicate(projectMembers.orgId, orgId),
1039	        eq(projectMembers.projectId, projectId),
1040	        eq(projectMembers.userId, userId),
1041	      ),
1042	    )
1043	    .get();
1044	  return row !== undefined;
1045	}
1046	/**
1047	 * Extracts `@handle` mentions from comment bodies and resolves them to member
1048	 * ids.
1049	 *
1050	 * A handle is the local part of a member's email address, lowercased — that
1051	 * is what the comment composer autocompletes and what `CommentService` feeds
1052	 * to the notification fan-out, so extraction and resolution must agree
1053	 * exactly. Mentions inside code spans and fenced blocks are ignored.
1054	 */
1055	import type { UserId } from "@/types/common";
1056	import type { MemberWithUser } from "@/types/member";
1057	
1058	/** `@` must start the line or follow whitespace/punctuation, never an email. */
1059	const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;
1060	
1061	function withoutCode(body: string): string {
1062	  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
1063	}
1064	
1065	/** The handle Taskflow addresses a member by, derived from their email. */
1066	export function handleOf(member: MemberWithUser): string {
1067	  return (member.user.email.split("@")[0] ?? "").toLowerCase();
1068	}
1069	
1070	/** Every distinct handle mentioned, in first-appearance order. */
1071	export function extractMentions(body: string): readonly string[] {
1072	  const seen = new Set<string>();
1073	  const handles: string[] = [];
1074	
1075	  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
1076	    const handle = (match[2] ?? "").toLowerCase();
1077	    if (handle === "" || seen.has(handle)) continue;
1078	    seen.add(handle);
1079	    handles.push(handle);
1080	  }
1081	
1082	  return handles;
1083	}
1084	
1085	/**
1086	 * Maps the mentions in `body` onto the ids of members who actually exist in
1087	 * the organization. Unknown handles are silently dropped — a typo must never
1088	 * fail the comment write.
1089	 */
1090	export function resolveMentions(
1091	  body: string,
1092	  members: readonly MemberWithUser[],
1093	): readonly UserId[] {
1094	  const byHandle = new Map<string, UserId>();
1095	  for (const member of members) {
1096	    byHandle.set(handleOf(member), member.userId);
1097	  }
1098	
1099	  const resolved: UserId[] = [];
1100	  const seen = new Set<UserId>();
1101	  for (const handle of extractMentions(body)) {
1102	    const userId = byHandle.get(handle);
1103	    if (userId === undefined || seen.has(userId)) continue;
1104	    seen.add(userId);
1105	    resolved.push(userId);
1106	  }
1107	
1108	  return resolved;
1109	}
1110	
1111	/** Wraps every mention in a span so the comment renderer can style it. */
1112	export function highlightMentions(body: string): string {
1113	  return body.replace(
1114	    MENTION_PATTERN,
1115	    (_match, prefix: string, handle: string) =>
1116	      `${prefix}<span class="mention">@${handle}</span>`,
1117	  );
1118	}
1119	import type {
1120	  EventHandler,
1121	  TaskflowEventMap,
1122	  TaskflowEventPayload,
1123	  TaskflowEventType,
1124	  Unsubscribe,
1125	} from "@/types/event";
1126	
1127	/**
1128	 * In-process, typed publish/subscribe bus.
1129	 *
1130	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
1131	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
1132	 * every reactive concern `subscribe()`s at module init (see
1133	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
1134	 * throwing handler never fails the emit or the sibling handlers.
1135	 */
1136	
1137	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
1138	
1139	const handlers = new Map<TaskflowEventType, HandlerSet>();
1140	
1141	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
1142	
1143	/** Registers a handler for one event type. Call the return value to detach. */
1144	export function subscribe<K extends TaskflowEventType>(
1145	  type: K,
1146	  handler: EventHandler<K>,
1147	): Unsubscribe {
1148	  const set = handlers.get(type) ?? new Set();
1149	  set.add(handler as EventHandler<TaskflowEventType>);
1150	  handlers.set(type, set);
1151	  return () => {
1152	    set.delete(handler as EventHandler<TaskflowEventType>);
1153	  };
1154	}
1155	
1156	/** Registers a handler that detaches itself after the first delivery. */
1157	export function subscribeOnce<K extends TaskflowEventType>(
1158	  type: K,
1159	  handler: EventHandler<K>,
1160	): Unsubscribe {
1161	  const off = subscribe(type, (payload) => {
1162	    off();
1163	    return handler(payload);
1164	  });
1165	  return off;
1166	}
1167	
1168	/**
1169	 * Publishes an event to every subscriber. Resolves once all handlers settle;
1170	 * rejected handlers are reported to the error sinks, never rethrown.
1171	 */
1172	export async function emit<K extends TaskflowEventType>(
1173	  type: K,
1174	  payload: TaskflowEventPayload<K>,
1175	): Promise<void> {
1176	  const set = handlers.get(type);
1177	  if (!set || set.size === 0) return;
1178	
1179	  const results = await Promise.allSettled(
1180	    [...set].map(async (handler) => {
1181	      await (handler as EventHandler<K>)(payload);
1182	    }),
1183	  );
1184	
1185	  for (const result of results) {
1186	    if (result.status === "rejected") {
1187	      reportHandlerError(type, result.reason);
1188	    }
1189	  }
1190	}
1191	
1192	/** Fire-and-forget variant for call sites that must not await delivery. */
1193	export function emitAndForget<K extends TaskflowEventType>(
1194	  type: K,
1195	  payload: TaskflowEventPayload<K>,
1196	): void {
1197	  void emit(type, payload).catch((error: unknown) => {
1198	    reportHandlerError(type, error);
1199	  });
1200	}
1201	
1202	export function onHandlerError(
1203	  sink: (type: TaskflowEventType, error: unknown) => void,
1204	): Unsubscribe {
1205	  errorSinks.add(sink);
1206	  return () => {
1207	    errorSinks.delete(sink);
1208	  };
1209	}
1210	
1211	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
1212	  for (const sink of errorSinks) {
1213	    try {
1214	      sink(type, error);
1215	    } catch {
1216	      // A failing error sink must never escalate.
1217	    }
1218	  }
1219	}
1220	
1221	/** Number of live subscribers for an event; used by tests and diagnostics. */
1222	export function subscriberCount(type: TaskflowEventType): number {
1223	  return handlers.get(type)?.size ?? 0;
1224	}
1225	
1226	/** Detaches every handler. Test-only — never call from application code. */
1227	export function resetEventBus(): void {
1228	  handlers.clear();
1229	  errorSinks.clear();
1230	}
1231	
1232	export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };
