662	  const scope: ArchiveScope = shouldFilterArchived(input)
663	    ? {}
664	    : { includeArchived: true };
665	  const filters = compact(
666	    orgPredicate(projects.orgId, input.orgId),
667	    livePredicate(projects.archivedAt, scope),
668	    input.status === undefined ? undefined : eq(projects.status, input.status),
669	    input.query === undefined
670	      ? undefined
671	      : like(projects.name, `%${input.query}%`),
672	  );
673	  const total = db
674	    .select({ value: count() })
675	    .from(projects)
676	    .where(and(...filters))
677	    .get();
678	  const rows = db
